control MyIngress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {

    register<bit<8>> (MAX) registers[100];
    bit<8> randNum;
    bit<8> tempRand;
    bit<8> count;
    bit<8> min = 1;
    bit<8> max = 100;
    bit<8> mid;
    bit<8> numGuesses;
    bit<8> secretNumber;
    bit<8> guessCount;

    action drop() {
        mark_to_drop(standard_metadata);
    }

    action ipv4_forward(macAddr_t dstAddr, egressSpec_t port) {
        standard_metadata.egress_spec = port;
        hdr.ethernet.srcAddr = hdr.ethernet.dstAddr;
        hdr.ethernet.dstAddr = dstAddr;
        hdr.ipv4.ttl = hdr.ipv4.ttl - 1;
    }

    table ipv4_lpm {
        key = {
            hdr.ipv4.dstAddr: lpm;
        }
        actions = {
            ipv4_forward;
            drop;
            NoAction;
        }
        size = 1024;
        default_action = drop();
    }

    action set_secret_number(){
        secretNumber = ((randNum % (max - min + 1)) + min);
    }

    action increment_guess_count(){
        guessCount = guessCount + 1;
    }

    action reset_guess_count(){
        guessCount = 0;
    }

    action send_response(bit<16> responseLength, bit<16> responseChecksum, bit<16> srcPort, bit<16> dstPort){
        hdr.udp.length = responseLength;
        hdr.udp.checksum = responseChecksum;
        hdr.udp.srcPort = srcPort;
        hdr.udp.dstPort = dstPort;
    }

    action verify_register(bit<8> value){
        if (value == secretNumber){
            return 1;
        }
        else if (value > secretNumber){
            max = value - 1;
        }
        else {
            min = value + 1;
        }
        return 0;
    }

    action binarySearch(){
        while (min <= max){
            mid = (min + max)/2;
            registers[mid].write(mid);
            if (verify_register(mid)){
                break;
            }
        }
    }

    apply {
        if (hdr.ipv4.isValid()){
            if (!meta.secretNumber.isInvalid()){
                if (meta.guessCount == 0){
                    reset_guess_count();
                }
                binarySearch();
                send_response((bit<16>)100, (bit<16>)0, (bit<16>)5000, (bit<16>)5001);
                increment_guess_count();
            }
            else {
                hash(tempRand, HashAlgorithm.cprand, (bit<32>)0, (bit<32>)0, (bit<32>)100);
                set_secret_number();
                reset_guess_count();
            }
            ipv4_lpm.apply();
        }
    }
}

